#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — RevenueCat go-live for RDM native (com.rdm.app)
# ──────────────────────────────────────────────────────────────────────────

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ENV_FILE="${ENV_FILE:-$SCRIPT_DIR/../.env}"
TOTAL_STAGES=11

banner "RDM RevenueCat go-live"

stage "App Store Connect — subscription products"
say "Create the iOS subscription products for package id com.rdm.app."
open_url "https://appstoreconnect.apple.com/apps"
step "Open the RDM iOS app (bundle id com.rdm.app)."
step "Go to Monetization → Subscriptions (or Features → In-App Purchases)."
step "Create a subscription group if needed, then add two auto-renewable products:"
note "  Suggested product ids: rdm_premium_monthly and rdm_premium_yearly"
step "Set pricing, localization, and submit for review when ready (sandbox works earlier)."
pause "Press Enter when both iOS products exist."

stage "Google Play Console — subscription products"
say "Create the Android subscription products for application id com.rdm.app."
open_url "https://play.google.com/console"
step "Open the RDM Android app (application id com.rdm.app)."
step "Monetize → Products → Subscriptions → Create subscription."
step "Add matching base plans for monthly and yearly (same commercial intent as iOS)."
note "  Suggested product ids: rdm_premium_monthly and rdm_premium_yearly"
step "Activate the products for a closed testing track."
pause "Press Enter when both Play products exist and are active for testing."

stage "RevenueCat — apps"
say "Connect both stores to one RevenueCat project."
open_url "https://app.revenuecat.com"
step "Create or open the RDM project."
step "Add an iOS app with bundle id com.rdm.app and connect App Store Connect."
step "Add an Android app with package name com.rdm.app and connect Google Play."
pause "Press Enter when both RevenueCat apps are connected."

stage "RevenueCat — products + entitlement premium"
say "Mirror store products and attach them to entitlement id premium."
open_url "https://app.revenuecat.com"
step "Project → Product catalog → import/link the App Store and Play products."
step "Create entitlement with identifier exactly: premium"
step "Attach both monthly and yearly products to entitlement premium."
pause "Press Enter when entitlement premium includes both products."

stage "RevenueCat — current offering"
say "Expose packages on the current offering so the Membership screen can list plans."
open_url "https://app.revenuecat.com"
step "Offerings → create or edit the Current offering."
step "Add packages (e.g. monthly + annual) pointing at the premium products."
step "Make sure this offering is marked Current / default."
pause "Press Enter when the current offering lists the packages."

stage "RevenueCat — restore behavior"
say "Keep membership bound to the original Better Auth user id."
open_url "https://app.revenuecat.com"
step "Project settings → General → Restore behavior."
step "Select Keep with original App User ID for Production and Sandbox."
confirm "Restore behavior is Keep with original App User ID?" || warn "Set it before shipping paid builds."

stage "Public SDK keys → apps/native/.env"
say "Copy PUBLIC SDK keys only (never the secret API key into EXPO_PUBLIC_*)."
open_url "https://app.revenuecat.com"
step "Project settings → API keys → Apple / iOS public app-specific key."
ask EXPO_PUBLIC_REVENUECAT_IOS_API_KEY "Paste iOS public SDK key:"
step "Android public app-specific key."
ask EXPO_PUBLIC_REVENUECAT_ANDROID_API_KEY "Paste Android public SDK key:"
write_env EXPO_PUBLIC_REVENUECAT_IOS_API_KEY "$EXPO_PUBLIC_REVENUECAT_IOS_API_KEY"
write_env EXPO_PUBLIC_REVENUECAT_ANDROID_API_KEY "$EXPO_PUBLIC_REVENUECAT_ANDROID_API_KEY"
write_env EXPO_PUBLIC_REVENUECAT_ENTITLEMENT_ID "premium"
note "Entitlement id locked to premium per go-live plan."

stage "EAS / build environment"
say "Public keys must also exist on each EAS build profile that should sell membership."
step "For each profile (preview/production), set:"
note "  EXPO_PUBLIC_REVENUECAT_IOS_API_KEY"
note "  EXPO_PUBLIC_REVENUECAT_ANDROID_API_KEY"
note "  EXPO_PUBLIC_REVENUECAT_ENTITLEMENT_ID=premium"
step "Example: eas env:create --name EXPO_PUBLIC_REVENUECAT_IOS_API_KEY --environment preview"
pause "Press Enter after EAS/env values are set (or skip if you only test local .env builds)."

stage "Native rebuild"
say "Billing needs a native binary — Expo Go cannot complete real purchases."
step "Build a Dev Client or store build that includes react-native-purchases."
note "  pnpm --filter native ios   or   eas build -p android --profile preview"
step "Install that build on a device/simulator with sandbox / license testing enabled."
pause "Press Enter when a billing-capable build is installed."

stage "Sandbox QA checklist"
say "Verify Membership end-to-end on at least one platform."
step "Sign in → Account → Membership: plans show localized prices (not coming soon)."
step "Purchase → status Active; kill/relaunch still Active for the same user."
step "Restore purchases works; Manage opens the store management URL when available."
step "Sign out / other account does not show Active for the prior purchase."
step "Cancel or expire in sandbox → status returns to Inactive."
confirm "Sandbox acceptance checks passed?" || warn "Re-run this stage after fixing store/RC config."

stage "Done — what code already does"
say "App code treats entitlement premium as membership and unlocks Focus Garden access (cosmetic only; no RDM minting)."
note "Skin art may still say not available yet — entitlement + Membership UI are the Phase 2 gate."
pause "Press Enter to finish."

finish
printf '  Next: open Membership in the native build. If plans are empty, re-check Current offering.\n\n'
